/**
 * Logos of a template.
 * @param id template id
 */
export function logosForTemplate(id: string): string[] | undefined {
    return templateLogos[id];
}

/**
 * Logos of an idea (preset).
 * @param id preset id
 */
export function logosForPreset(id: string): string[] | undefined {
    return presetLogos[id];
}

/**
 * Logo of a library.
 * @param id library id
 */
export function logosForLibrary(id: string): string[] | undefined {
    const slug = libraryLogos[id];
    return slug ? [slug] : undefined;
}

/**
 * Logo of a database, package manager or extra.
 * @param id database name, package manager id or extra id
 */
export function logosForOther(id: string): string[] | undefined {
    const slug = otherLogos[id];
    return slug ? [slug] : undefined;
}
